const { seg, lerp, eo, ei, eio, clamp01 } = kit;
const INKS = 'stroke:#2A2522;stroke-width:5;stroke-linejoin:round;stroke-linecap:round';
Object.assign(W, {
  // the wooden frame: posts at x 760 / 1160, beam underside at y 270, pulley at (960, 284)
  woodFrame(cls) { return '<g class="' + cls + '"><path d="M736 900 L748 250 H784 L796 900 Z M1124 900 L1136 250 H1172 L1184 900 Z" style="fill:#C99A62;' + INKS + '"/><path d="M770 260 V890 M1158 260 V890" style="fill:none;stroke:#A87C4E;stroke-width:5"/>' +
    '<rect x="700" y="226" width="520" height="48" rx="6" style="fill:#D9B07A;' + INKS + '"/><path d="M720 250 H1200" style="fill:none;stroke:#A87C4E;stroke-width:4"/><path d="M760 900 L690 900 L762 790 M1160 900 L1230 900 L1158 790" style="fill:none;stroke:#2A2522;stroke-width:22;stroke-linecap:round"/><path d="M760 900 L690 900 L762 790 M1160 900 L1230 900 L1158 790" style="fill:none;stroke:#C99A62;stroke-width:13;stroke-linecap:round"/>' +
    '<circle cx="960" cy="284" r="16" style="fill:#7D7A80;' + INKS + '"/></g>'; },
  // where a kit person's local point lands on the stage (x, y, s, flip, lean in degrees)
  personPoint(p, lx, ly) { const s = p.s || 1, f = p.flip ? -1 : 1, a = (p.lean || 0) * Math.PI / 180; const x = lx * s * f, y = ly * s; return [p.x + x * Math.cos(a) - y * Math.sin(a), (p.y || 0) + (p.bob || 0) + x * Math.sin(a) + y * Math.cos(a)]; },
});
kit.scene('bound', {
  init(kit) {
    const M = W.MOODS.stoneBlue;
    kit.stage.append(kit.h('<div class="ground"><div class="layer bound-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.stoneRoom(M, { seed: 5, floorY: 800, flagstones: true }) +
      W.glow(960, 360, 760, '#E8EEF2', 0.45) + '<ellipse cx="960" cy="908" rx="300" ry="24" style="fill:rgba(42,37,34,.18)"/>' + W.woodFrame('bound-frame') +
      '<path class="bound-rope" style="fill:none;stroke:#2A2522;stroke-width:10;stroke-linejoin:round;stroke-linecap:round"/><path class="bound-rope2" style="fill:none;stroke:#D8BE8A;stroke-width:5;stroke-linejoin:round;stroke-linecap:round"/>' +
      W.person('bound-a', { outfit: 'rags', expr: 'worried' }) + W.person('bound-b', { outfit: 'none' }) +
      '<g class="bound-tiepos"><g class="bound-tie"><rect x="-20" y="-12" width="40" height="24" rx="6" style="fill:#D8BE8A;' + INKS + '"/><path d="M-12 -12 V12 M0 -12 V12 M12 -12 V12" style="fill:none;stroke:#A88E5A;stroke-width:3"/></g></g>' +
      '<g class="bound-tunic"><path d="M-40 -60 Q-40 -76 -28 -76 H28 Q40 -76 40 -60 L52 40 L40 30 L30 46 L18 32 L6 48 L-6 32 L-18 46 L-30 30 L-40 44 L-52 40 Z" style="fill:#8C6C4F;' + INKS + '"/></g>' +
      W.person('bound-e', { outfit: 'exec' }) + '</svg></div><div class="vignette"></div><p class="hand-label tag bound-tag" style="left:110px;top:90px">Upside down</p></div>'));
    const s = (c) => kit.stage.querySelector(c);
    this.a = W.bindPerson(kit.stage, 'bound-a'); this.b = W.bindPerson(kit.stage, 'bound-b'); this.e = W.bindPerson(kit.stage, 'bound-e');
    this.ga = s('.bound-a'); this.gb = s('.bound-b');
    Object.assign(this, { cam: s('.bound-cam'), rope: s('.bound-rope'), rope2: s('.bound-rope2'), tiepos: s('.bound-tiepos'), tie: s('.bound-tie'), tunic: s('.bound-tunic'), frame: s('.bound-frame'), tag: s('.bound-tag') });
  },
  render(t) {
    this.cam.style.transformOrigin = '960px 520px';
    this.cam.style.transform = 'scale(' + lerp(1.0, 1.06, eio(seg(t, 0, 5.6))).toFixed(4) + ')';
    // 'stripped': the tunic flies off and the plain stick body is left
    const stripped = t >= 0.84;
    this.ga.style.display = stripped ? 'none' : ''; this.gb.style.display = stripped ? '' : 'none';
    const fl = clamp01((t - 0.84) / 0.7);
    this.tunic.setAttribute('transform', 'translate(' + lerp(960, 560, fl).toFixed(1) + ' ' + (790 - 520 * fl + 700 * fl * fl).toFixed(1) + ') rotate(' + (-300 * fl).toFixed(1) + ')');
    this.tunic.style.opacity = t < 0.84 || fl >= 1 ? 0 : 1 - fl * 0.3;
    // the hoist: feet rise to the pulley while the body turns over
    const h = eio(seg(t, 3.0, 3.95)), sway = t > 3.95 ? 5 * Math.sin((t - 3.95) * 3.2) * Math.exp(-(t - 3.95) * 1.2) : 0;
    const tied = t >= 1.64;
    const P = { x: 960 + 30 * Math.sin(Math.PI * h), y: lerp(900, 312, h), s: 1.6, lean: 180 * h + sway };
    const base = { expr: 'worried', blink: W.blinkAt(t, [0.5, 2.6]), head: Math.sin(t * 2) * 2, legL: tied ? 4 : 0, legR: tied ? -4 : 0, a1: lerp(-8, 172, h), b1: lerp(8, 188, h), sq: W.take(t, 0.84) };
    W.posePerson(this.a, Object.assign({}, P, base)); W.posePerson(this.b, Object.assign({}, P, base, { expr: t > 3.0 ? 'surprised' : 'worried', sq: W.take(t, 3.0) }));
    // the tie at the ankles (local point just above the feet)
    const ank = W.personPoint(P, 0, -14);
    this.tiepos.setAttribute('transform', 'translate(' + ank[0].toFixed(1) + ' ' + ank[1].toFixed(1) + ') rotate(' + P.lean.toFixed(1) + ')');
    W.pop(this.tie, t, 1.64);
    // the executioner hauls: two pulls during the hoist
    const pull = t > 3.0 && t < 3.95 ? Math.abs(Math.sin((t - 3.0) * Math.PI / 0.47)) : 0;
    const E = { x: 1440, y: 900, s: 1.6, flip: true, bob: 6 * pull };
    const a1 = lerp(-165, -125, pull), a2 = lerp(-10, 20, pull);
    W.posePerson(this.e, Object.assign({}, E, { a1, a2, a3: 0, b1: lerp(150, 120, pull), b2: 10, expr: 'neutral', head: -6 * pull }));
    const sh = [22, -132], r1 = a1 * Math.PI / 180, r2 = (a1 + a2) * Math.PI / 180;
    const hand = W.personPoint(E, sh[0] - 36 * Math.sin(r1) - 34 * Math.sin(r2), sh[1] + 36 * Math.cos(r1) + 34 * Math.cos(r2));
    const start = tied ? ank : [1100 + 6 * Math.sin(t * 2), 420];
    const d = 'M' + start[0].toFixed(1) + ' ' + start[1].toFixed(1) + ' L960 268 L1150 252 L' + hand[0].toFixed(1) + ' ' + hand[1].toFixed(1);
    this.rope.setAttribute('d', d); this.rope2.setAttribute('d', d);
    // 'wooden frame': the beam takes the weight
    const bump = t > 4.4 ? -6 * Math.exp(-(t - 4.4) * 6) * Math.sin((t - 4.4) * 28) : 0;
    this.frame.setAttribute('transform', 'translate(0 ' + bump.toFixed(1) + ')');
    W.pop(this.tag, t, 3.52, 'left');
  },
});
